const payload=$input.first().json;
if (payload.allSynthetic!==true || !payload.job || !Array.isArray(payload.candidates)) {
 throw new Error('Only a synthetic job and candidate list are accepted by the recruiter demo.');
}
const job=payload.job;
if(!job.id||!Array.isArray(job.requiredSkills)||job.requiredSkills.length===0||!Number.isFinite(job.minimumExperienceYears)){
 throw new Error('Incomplete demo job. Expected id, requiredSkills and minimumExperienceYears.');
}
return [{json:{job,candidates:payload.candidates,allSynthetic:true,origin:'Isolated demo. No BAIT database access.'}}];

const x=$input.first().json;
const levels={'high school':1,'associate':1.5,'bachelor':2,'master':3,'phd':4};
const required=levels[String(x.job.minimumEducation||'').toLowerCase()];
if(!required)throw new Error('Unknown education eligibility requirement for test job');
const eligible=[],excluded=[];
for(const c of x.candidates){
 const education=levels[String(c.education||'').toLowerCase()];
 if(!c.id||!Array.isArray(c.skills)||!Number.isFinite(c.experienceYears)||!education){
  excluded.push({id:c.id||'unknown',reason:'Missing or unrecognized candidate evidence'});
 }else if(education<required){
  excluded.push({id:c.id,reason:`Below minimum ${x.job.minimumEducation} education`});
 }else{eligible.push(c)}
}
return [{json:{...x,eligible,excluded}}];

// Weighted scoring with RECRUITER-CONFIGURABLE weights and threshold (defaults 40/30/30, 70).
// Hard eligibility (education) was already applied in the previous node.
const x = $input.first().json;
const W = x.job.weights || { skills: 40, experience: 30, education: 30 };
const T = Number.isFinite(x.job.threshold) ? x.job.threshold : 70;
if (W.skills + W.experience + W.education !== 100) throw new Error('Weights must add up to 100');
const levels = { 'high school': 1, 'associate': 1.5, 'bachelor': 2, 'master': 3, 'phd': 4 };
const required = levels[String(x.job.minimumEducation || '').toLowerCase()];
const norm = s => String(s || '').trim().toLowerCase();
const scored = x.eligible.map(c => {
  const matched = x.job.requiredSkills.filter(k => c.skills.some(s => norm(s) === norm(k)));
  const missing = x.job.requiredSkills.filter(k => !matched.includes(k));
  // Skills: share of required skills held. Experience: years vs minimum (capped at 100%).
  // Education: meeting the minimum earns 75% of its weight, exceeding it earns 100%.
  const skills = Math.round(W.skills * matched.length / x.job.requiredSkills.length);
  const experience = Math.round(x.job.minimumExperienceYears > 0
    ? W.experience * Math.min(c.experienceYears / x.job.minimumExperienceYears, 1) : W.experience);
  const education = Math.round(W.education * (levels[norm(c.education)] > required ? 1 : 0.75));
  const score = skills + experience + education;
  return { id: c.id, name: c.name, score, matchedSkills: matched, missingSkills: missing,
    education: c.education, experienceYears: c.experienceYears,
    recommendation: score >= T ? 'SHORTLIST' : 'BELOW_THRESHOLD',
    scoreBreakdown: { skills, experience, education } };
});
scored.sort((a, b) => b.score - a.score || a.id.localeCompare(b.id));
const shortlist = scored.filter(c => c.recommendation === 'SHORTLIST');
return [{ json: { job: x.job, allSynthetic: true, shortlist: shortlist.slice(0, 3),
  otherEligible: scored.filter(c => c.recommendation === 'BELOW_THRESHOLD'), excluded: x.excluded,
  allEvaluations: scored, totalCandidates: x.candidates.length, weights: W, threshold: T,
  scoringMethod: 'Recruiter weights skills ' + W.skills + ' / experience ' + W.experience + ' / education ' + W.education + ', threshold ' + T + '. Decision support, not a hiring probability.' } }];

const x=$input.first().json;
let message=`RECRUITER DEMO: ranked candidates for ${x.job.title}

`;
x.shortlist.forEach((c,i)=>{message+=`${i+1}. ${c.name} — ${c.score}/100
Matched: ${c.matchedSkills.join(', ')||'none'}; Experience ${c.experienceYears} year(s); ${c.education}.

`});
message+=`Eligibility exclusions: ${x.excluded.length}. Below-threshold candidates: ${x.otherEligible.length}.
Synthetic data; recommendations are for human review, NOT automated hiring decisions.`;
return [{json:{...x,message}}];
